const { useMemo, useState, useEffect, useLayoutEffect, useRef, useCallback, useSyncExternalStore } = React;

// These six all start out pointing at the deploy-time snapshot, and are
// `let` (not `const`) so useLiveSiteData() below can swap each one for
// fresher data fetched at runtime from the site-data-current function - the
// same live-without-a-deploy pattern already used for odds. Every read of
// these goes through a function call made at render/access time (baseTeam(),
// getPlayers(), getHistorySnapshot(), etc.), never a top-level destructure,
// so reassigning the binding is safe.
//
// The small ones are still embedded in the page as <script type="application/json">
// blocks. The two big ones - history (~400 KB) and impact players (~140 KB) -
// are NOT embedded any more: they used to ride along inside every one of the
// ~4,000 static pages, and the embedded history copy also lagged data/history.json
// by a week whenever nobody re-synced it by hand. bootApp() at the bottom of
// this file fetches both straight from /data/ (the canonical files the refresh
// jobs commit) before the first render, so the seed is always as fresh as the
// deploy and the HTML stays small. They start empty here only so that any
// code path which runs before bootApp() resolves still sees the right shape.
let TEAMS_DATA = JSON.parse(document.getElementById('teams-data').textContent);
let PLAYERS_DATA = { players: {} };
let SCHEDULE_DATA = JSON.parse(document.getElementById('schedule-data').textContent);
let HISTORY_DATA = { weeks: [] };
let PRESEASON_DATA = JSON.parse(document.getElementById('preseason-data').textContent);
let PLAYOFFS_DATA = JSON.parse(document.getElementById('playoffs-data').textContent);
// ODDS_DATA starts out pointing at whatever was embedded in the page at last
// deploy (a periodic mirror - see odds-2026.json's sourceNote). useLiveOddsData()
// below swaps it for fresher data fetched at runtime from the odds-current
// function, which the odds-refresh scheduled task writes to every few minutes
// without triggering a redeploy. getOdds() always reads through this binding,
// so it picks up whichever version is current at call time.
let ODDS_DATA = JSON.parse(document.getElementById('odds-data').textContent);
// STADIUMS_DATA is static reference data (lat/lon + isDome per team, plus
// international venues) - it doesn't change at runtime, so unlike the others
// there's no live-refresh hook for it, just a one-time parse.
const STADIUMS_DATA = JSON.parse(document.getElementById('stadiums-data').textContent);
// WEATHER_DATA follows the same live-without-a-deploy pattern as ODDS_DATA -
// starts out empty/embedded, useLiveWeatherData() swaps it for fresher data
// from weather-current, written by the weather-refresh scheduled script.
let WEATHER_DATA = JSON.parse(document.getElementById('weather-data').textContent);
// The model's call on each game as frozen just before that game's kickoff,
// keyed by week then "away-home" (see getFrozenPrediction). Nothing is
// embedded at deploy time - unlike odds and weather this has no useful
// pre-kickoff value, since a game that hasn't started has nothing frozen -
// so it starts empty and useFrozenPredictions() fills in whichever week is
// on screen from predictions-current. A card for a live or final game reads
// through this instead of recomputing, so the number it shows is what the
// model said before kickoff rather than what it would say now, after that
// game's injury report, weather and lines have all moved on.
let PREDICTIONS_DATA = { weeks: {} };

// Sportsbook preference: no sportsbook offers a public login/API for a
// third-party site to pull an individual bettor's personal odds, so this is
// a saved local preference (which book's line to display), not a real
// account login. When the chosen book has no line of its own yet, we fall
// back to the default aggregated line, labeled as DraftKings (ESPN's
// official sportsbook partner as of the 2025 ESPN Bet shutdown).
const SPORTSBOOKS = [
  { id: "draftkings", label: "DraftKings", short: "DraftKings" },
  { id: "fanduel", label: "FanDuel", short: "FanDuel" },
  { id: "betmgm", label: "BetMGM", short: "BetMGM" },
  { id: "caesars", label: "Caesars Sportsbook", short: "Caesars" },
  { id: "betrivers", label: "BetRivers", short: "BetRivers" },
];
// Leagues (create/join/invite-code) backend and modal are built and working,
// but there's no standings or pick-submission UI yet - hiding the entry
// points until the rest of the league pages exist. Flip to true to bring
// back the "Leagues" toolbar button and "My Leagues" account menu item.
const LEAGUES_UI_ENABLED = true;

const DEFAULT_SPORTSBOOK_ID = "draftkings";
const SPORTSBOOK_STORAGE_KEY = "blitz-odds-sportsbook";

// The Games tab's game-type selector. Deliberately the same four formats a
// league can be run in, because the whole point of the control is to make
// the Games tab answer the question the reader's own pool actually asks -
// a straight-up player wants a winner, an ats player wants a side of the
// line, and the two reads routinely disagree. The ids match league
// `format` values 1:1 so both surfaces run through computeBlitzEdge().
/* The Playbook tab's label and icon, as constants rather than literals in
 * TabBar, because the name is still provisional - "Playbook" is a working
 * title and renaming it should be a one-line change here, not a hunt
 * through JSX. The route id stays "picks" either way: that's in TAB_ROUTES,
 * in URLs, and in push-notification deep links, so it isn't a display
 * string and must not be renamed with the label. */
const PLAYBOOK_TAB_LABEL = "Playbook";
/* PLAYBOOK_TAB_ICON is the emoji fallback, kept because TabBar still renders
 * it for any tab without an image (and because it's the thing to fall back
 * to if the artwork ever has to come out). PLAYBOOK_TAB_IMG is what actually
 * shows. Root-relative, not relative: the same markup is served from
 * /teams/{slug}/ and /games/{season}/... by build-static-pages.mjs, where a
 * relative path would resolve against the nested directory and 404. */
const PLAYBOOK_TAB_ICON = "\u{1F4CB}";
const PLAYBOOK_TAB_IMG = "/branding/tab-icon-playbook.png";

const GAME_TYPE_STORAGE_KEY = "blitz-odds-game-type";
const DEFAULT_GAME_TYPE = "straight_up";
// `short` is what a phone-width command bar shows. Only ats actually needs
// shortening - "SU"/"Surv" would save a few pixels the bar doesn't need and
// cost the reader the word.
const GAME_TYPES = [
  { id: "straight_up", label: "Straight Up", short: "Straight Up", desc: "Just pick the winner" },
  { id: "confidence", label: "Confidence", short: "Confidence", desc: "Rank picks by points" },
  { id: "ats", label: "Against the Spread", short: "ATS", desc: "Pick a side of the line" },
  { id: "survivor", label: "Survivor", short: "Survivor", desc: "One team a week, no repeats" },
];

// iOS Safari doesn't reliably honor `body { overflow: hidden }` as a scroll
// lock - the page can still rubber-band scroll behind an open modal, and
// when the style is removed the browser's viewport metrics can end up out
// of sync, causing `position: fixed` elements (like the bottom tab bar) to
// stop tracking the real viewport and drift into the document flow instead.
// The reliable cross-browser fix is to pin <body> itself to position:fixed
// at a negative top offset equal to the current scroll position while a
// modal is open, then restore both the styles and the scroll position when
// it closes. Nest-safe via a simple open-modal counter so stacked modals
// (rare, but possible) don't stomp each other's saved scroll position.
let _scrollLockCount = 0;
let _scrollLockY = 0;
function lockBodyScroll() {
  if (_scrollLockCount === 0) {
    _scrollLockY = window.scrollY || window.pageYOffset || 0;
    const body = document.body;
    body.style.position = "fixed";
    body.style.top = `-${_scrollLockY}px`;
    body.style.left = "0";
    body.style.right = "0";
    body.style.width = "100%";
  }
  _scrollLockCount++;
}
function unlockBodyScroll() {
  _scrollLockCount = Math.max(0, _scrollLockCount - 1);
  if (_scrollLockCount === 0) {
    const body = document.body;
    body.style.position = "";
    body.style.top = "";
    body.style.left = "";
    body.style.right = "";
    body.style.width = "";
    window.scrollTo(0, _scrollLockY);
  }
}

// Time zone preference for displayed kickoff times. "auto" (the default)
// means "whatever the device's own zone is right now", resolved fresh each
// time rather than saved as a fixed zone, so someone who travels still sees
// local kickoff times without touching Settings. Picking any other entry
// pins the display to that zone and is remembered across visits.
const TIMEZONE_AUTO = "auto";
const TIMEZONE_STORAGE_KEY = "blitz-odds-timezone";
const TIMEZONES = [
  { id: "America/New_York", label: "Eastern Time" },
  { id: "America/Chicago", label: "Central Time" },
  { id: "America/Denver", label: "Mountain Time" },
  { id: "America/Phoenix", label: "Arizona (no DST)" },
  { id: "America/Los_Angeles", label: "Pacific Time" },
  { id: "America/Anchorage", label: "Alaska Time" },
  { id: "Pacific/Honolulu", label: "Hawaii Time" },
  { id: "America/Puerto_Rico", label: "Atlantic Time" },
  { id: "Europe/London", label: "London" },
  { id: "Europe/Paris", label: "Central Europe" },
  { id: "Asia/Tokyo", label: "Tokyo" },
  { id: "Australia/Sydney", label: "Sydney" },
];

/** The device's own IANA zone (e.g. "America/Chicago"), used whenever the
 *  saved preference is TIMEZONE_AUTO. Falls back to Eastern - the schedule's
 *  own native zone - if the browser won't say (very old browsers only). */
function detectDeviceTimezone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "America/New_York";
  } catch (e) {
    return "America/New_York";
  }
}

function getSportsbookLabel(id) {
  const book = SPORTSBOOKS.find(b => b.id === id);
  return book ? book.label : id;
}

function getSportsbookShortLabel(id) {
  const book = SPORTSBOOKS.find(b => b.id === id);
  return book ? book.short : id;
}

