/** Sits at the right of the week command bar and decides which read every
 *  card's Blitz Edge row shows. Carries the brand mark rather than a plain
 *  caret because the thing it changes is the Blitz Edge recommendation, not
 *  the schedule. Label abbreviates on a phone so the bar never wraps. */
function GameTypePicker({ gameType, setGameType }) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef(null);
  const current = GAME_TYPES.find(t => t.id === gameType) || GAME_TYPES[0];

  useEffect(() => {
    function handleOutsideClick(e) {
      if (containerRef.current && !containerRef.current.contains(e.target)) setOpen(false);
    }
    function handleKeyDown(e) {
      if (e.key === "Escape") setOpen(false);
    }
    document.addEventListener("mousedown", handleOutsideClick);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  return (
    <div className="cmd-gametype" ref={containerRef}>
      <button
        type="button"
        className="gametype-trigger"
        data-tour="game-type"
        onClick={() => setOpen(o => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={"Game type: " + current.label}
      >
        <img src="/branding/blitz-edge-icon.png" alt="" className="gametype-icon" width="160" height="120" decoding="async" />
        <span className="gametype-label-full">{current.label}</span>
        <span className="gametype-label-short">{current.short}</span>
        <span className={"week-nav-chevron" + (open ? " open" : "")}>
          <ChevronIcon direction="down" size={11} />
        </span>
      </button>

      {open && (
        <div className="gametype-panel" role="listbox">
          <div className="gametype-group-label">Game type</div>
          {GAME_TYPES.map(t => (
            <button
              key={t.id}
              type="button"
              role="option"
              aria-selected={t.id === gameType}
              className={"gametype-item" + (t.id === gameType ? " active" : "")}
              onClick={() => { setGameType(t.id); setOpen(false); }}
            >
              <span className="gametype-item-name">{t.label}</span>
              <span className="gametype-item-desc">{t.desc}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

