/** Saved time zone preference for displayed kickoff times: TIMEZONE_AUTO
 *  (the default) or one of TIMEZONES' ids. Persisted the same way as the
 *  sportsbook/theme preferences - a local-only setting remembered across
 *  visits via localStorage, not tied to any account. */
function useTimezoneManager() {
  const [tzId, setTzId] = useState(() => {
    try {
      const saved = localStorage.getItem(TIMEZONE_STORAGE_KEY);
      return saved === TIMEZONE_AUTO || TIMEZONES.some(z => z.id === saved) ? saved : TIMEZONE_AUTO;
    } catch (e) {
      return TIMEZONE_AUTO;
    }
  });

  useEffect(() => {
    try { localStorage.setItem(TIMEZONE_STORAGE_KEY, tzId); } catch (e) {}
  }, [tzId]);

  // The zone actually used for formatting: re-resolved on every render when
  // set to "auto" so a device zone change (e.g. travel) takes effect
  // immediately without the user having to touch Settings.
  const resolvedTz = tzId === TIMEZONE_AUTO ? detectDeviceTimezone() : tzId;

  return [tzId, setTzId, resolvedTz];
}

function TimezonePicker({ tzId, setTzId, resolvedTz }) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef(null);
  const current = tzId === TIMEZONE_AUTO
    ? TIMEZONES.find(z => z.id === resolvedTz)
    : TIMEZONES.find(z => z.id === tzId);
  const currentLabel = tzId === TIMEZONE_AUTO
    ? `Auto${current ? ` (${current.label})` : ""}`
    : (current ? current.label : tzId);

  useEffect(() => {
    function handleOutsideClick(e) {
      if (containerRef.current && !containerRef.current.contains(e.target)) setOpen(false);
    }
    function handleKeyDown(e) {
      if (e.key === "Escape") setOpen(false);
    }
    document.addEventListener("mousedown", handleOutsideClick);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  function pick(id) {
    setTzId(id);
    setOpen(false);
  }

  return (
    <div className="book-picker" ref={containerRef}>
      <button
        className="book-picker-trigger"
        onClick={() => setOpen(o => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        title="Choose which time zone kickoff times are shown in"
      >
        <span className="book-picker-label-dim">Time zone:</span>
        <span>{currentLabel}</span>
        <span className={"book-picker-chevron" + (open ? " open" : "")}><ChevronIcon direction="down" size={12} /></span>
      </button>
      {open && (
        <div className="book-picker-panel" role="listbox">
          <button
            className={"book-picker-item" + (tzId === TIMEZONE_AUTO ? " active" : "")}
            role="option"
            aria-selected={tzId === TIMEZONE_AUTO}
            onClick={() => pick(TIMEZONE_AUTO)}
          >
            <span>Auto (this device)</span>
            <span className="book-picker-label-dim">Default</span>
          </button>
          {TIMEZONES.map(z => (
            <button
              key={z.id}
              className={"book-picker-item" + (tzId === z.id ? " active" : "")}
              role="option"
              aria-selected={tzId === z.id}
              onClick={() => pick(z.id)}
            >
              <span>{z.label}</span>
            </button>
          ))}
          <div className="book-picker-hint">
            Saved on this device only. Kickoff times are listed in Eastern by the league; this only changes
            how they're displayed here.
          </div>
        </div>
      )}
    </div>
  );
}

