/** Reads a league invite link once at App-mount time. The current form is
 *  the path /join/{code}; the older query forms - ?joinCode=XXXX (private
 *  leagues, matches league-join.mts's inviteCode body param) and
 *  ?joinLeague=ID (public leagues, matches its leagueId param) - are still
 *  read and always will be, since invites already sitting in inboxes don't
 *  expire on our schedule.
 *
 *  What neither form uses is a URL hash: Netlify Identity's own email flows
 *  (confirm/invite/recovery) hijack #confirmation_token=...-style fragments,
 *  and some email click-trackers drop fragments entirely when rewriting
 *  links. A path also survives both, and unlike a query string it can be
 *  matched by a native app's Universal Links later. */
function getInitialLeagueJoin() {
  try {
    const route = parseLocationPath(window.location.pathname);
    if (route && route.join) return route.join;
  } catch (e) {}
  try {
    const params = new URLSearchParams(window.location.search);
    const code = params.get("joinCode");
    if (code && code.trim()) return { type: "code", value: code.trim().toUpperCase() };
    const leagueId = params.get("joinLeague");
    if (leagueId && leagueId.trim()) return { type: "leagueId", value: leagueId.trim() };
  } catch (e) {}
  return null;
}

/** Reads the current URL once at App-mount time. Wrapped so every initial
 *  useState below can call it independently (each only runs its lazy
 *  initializer on first render, so the repeat calls cost nothing) without
 *  threading a single computed value through multiple useState calls. */
function getInitialRoute() {
  try { return parseLocationPath(window.location.pathname); } catch (e) { return null; }
}

// Lets links from outside the SPA land directly on a tab. The real form is
// a path ("/news"); the old hash form ("/#news") is still honoured because
// it's sitting in already-sent emails, the archive's static tab nav, and
// people's bookmarks - App rewrites it to the path on arrival rather than
// leaving two URLs for the same screen. Falls back to "games" so a stray
// "#" or an unknown tab never lands nowhere.
const TAB_IDS = Object.keys(TAB_ROUTES);
function getInitialTab(leaguesEnabled) {
  // A league invite link always wins, regardless of path or hash - it's a
  // much stronger signal of intent than whatever tab happened to be in the
  // URL, and email link-tracking wrappers sometimes drop the hash anyway
  // (see getInitialLeagueJoin).
  if (leaguesEnabled && getInitialLeagueJoin()) return "league";
  try {
    const route = parseLocationPath(window.location.pathname);
    if (route && route.tab && !route.isRoot && (route.tab !== "league" || leaguesEnabled)) return route.tab;
    // Team and game pages carry a `view` but no `tab` - they live under the
    // Games tab, which used to be the fallback below and no longer is. Without
    // this, a direct hit or crawl of /teams/{slug} or /games/{season}/... would
    // open the Home tab and the route sync effect would then rewrite the URL
    // to "/", losing the page entirely.
    if (route && (route.view === "team" || route.view === "game" || route.view === "weekHub")) return "games";
  } catch (e) {}
  try {
    const hash = (window.location.hash || "").replace(/^#/, "");
    if (TAB_IDS.includes(hash) && (hash !== "league" || leaguesEnabled)) return hash;
  } catch (e) {}
  return ROOT_TAB;
}

/* ---------------------------------------------------------------------- *
 * Account screens
 *
 * Signup, "confirm your email", forgot-password and reset all live here.
 * They exist because Netlify Identity's email settings - custom template,
 * custom sender - are Pro-plan features and this site is on Personal, so
 * every mail GoTrue sends would be its unbranded default from
 * no-reply@netlify.com. The way around that is to never let GoTrue send:
 * accounts are created server-side with confirm:true (auth-signup.mts) and
 * password resets run on our own tokens (auth-forgot/auth-reset.mts), with
 * both emails going out through Resend like everything else the site sends.
 *
 * Sign-IN still goes through the widget, or through auth.signIn against the
 * same GoTrue client - either way it sends no email, so it needed no
 * replacement.
 * ---------------------------------------------------------------------- */

const AUTH_MIN_PASSWORD = 8;

/* The overlay every deliberately-opened account screen sits in. One place
   for backdrop dismissal, Escape, scroll lock and the close button, rather
   than four panels each remembering three of the four.

   `onClose` null renders it as a page instead (no backdrop, no dismissal) -
   that's the confirm-your-email gate, which reuses the same card but must
   not be dismissible, since dismissing it would reveal an app whose every
   authenticated control the server refuses. */
function AuthOverlay({ onClose, label, children }) {
  useEffect(() => {
    if (!onClose) return;
    function onKey(e) { if (e.key === "Escape") onClose(); }
    document.addEventListener("keydown", onKey);
    // Locking the page behind a modal is what stops a phone scrolling the
    // app under the card while someone types into it. This has to go
    // through lockBodyScroll rather than setting overflow:hidden directly -
    // iOS Safari doesn't honour the overflow lock, and removing it leaves
    // the viewport metrics out of sync, which drops the fixed bottom tab
    // bar and the sticky header out of the viewport and into document flow
    // for the rest of the session. Every other modal already uses the
    // helper; this one was the last holdout.
    lockBodyScroll();
    return () => {
      document.removeEventListener("keydown", onKey);
      unlockBodyScroll();
    };
  }, [onClose]);

  if (!onClose) {
    return <div className="authscreen is-page">{children}</div>;
  }

  return (
    <div className="authscreen is-modal" role="dialog" aria-modal="true" aria-label={label}>
      <div className="authscreen-backdrop" onClick={onClose} />
      {children}
    </div>
  );
}

/* Corner dismiss. Separate from the Cancel button in the footer on purpose:
   Cancel is the answer to "do you want to do this", the X is the answer to
   "I opened this by accident", and on a phone they want to be in different
   places. */
function AuthCloseButton({ onClose }) {
  if (!onClose) return null;
  return (
    <button type="button" className="authcard-close" aria-label="Close" onClick={onClose}>
      {"\u00D7"}
    </button>
  );
}

/* Four segments, deliberately not a score out of ten. Length is doing most
   of the work and the bar should say so, rather than implying that adding a
   punctuation mark to "password1" has bought anything. */
function authPasswordScore(v) {
  let score = 0;
  if (v.length >= AUTH_MIN_PASSWORD) score++;
  if (v.length >= 12) score++;
  if (/[^a-zA-Z0-9]/.test(v)) score++;
  if (/[0-9]/.test(v) && /[a-zA-Z]/.test(v)) score++;
  return score;
}

/* Google's own mark, inline rather than an <img>, so it inherits nothing and
   loads with the rest of the page. The four brand colours are fixed by
   Google's guidelines and deliberately not theme tokens - a recoloured G is
   a misused logo. */
function GoogleMark() {
  return (
    <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true" focusable="false">
      <path fill="#4285F4" d="M45.1 24.5c0-1.6-.1-3.1-.4-4.5H24v8.5h11.8c-.5 2.7-2 5-4.4 6.6v5.5h7.1c4.1-3.8 6.6-9.4 6.6-16.1z" />
      <path fill="#34A853" d="M24 46c5.9 0 10.9-2 14.5-5.4l-7.1-5.5c-2 1.3-4.5 2.1-7.4 2.1-5.7 0-10.5-3.8-12.2-9H4.5v5.7C8.1 41.1 15.4 46 24 46z" />
      <path fill="#FBBC05" d="M11.8 28.2c-.4-1.3-.7-2.7-.7-4.2s.2-2.9.7-4.2v-5.7H4.5C3 17.1 2.1 20.4 2.1 24s.9 6.9 2.4 9.9l7.3-5.7z" />
      <path fill="#EA4335" d="M24 10.8c3.2 0 6.1 1.1 8.4 3.3l6.3-6.3C34.9 4.2 29.9 2 24 2 15.4 2 8.1 6.9 4.5 14.1l7.3 5.7c1.7-5.2 6.5-9 12.2-9z" />
    </svg>
  );
}

/* The provider block that sits above the email fields on both the sign-in and
   the create-account panels.

   Above rather than below, and on both screens, because "continue with
   Google" is the same single act either way - the person doing it neither
   knows nor cares whether they already have an account, and making them pick
   the right screen first is asking a question only our database can answer. */
function AuthProviderBlock({ auth, context, onNeedTermsConsent }) {
  /* On the signup screen the Google button creates an account, and there is
     no form of ours between here and Google to carry a terms checkbox - so
     the handoff is interrupted by the consent dialog first, and resumed on
     accept. On the LOGIN screen it isn't: the overwhelmingly common case
     there is an existing account signing back in, and stopping all of them
     to re-accept terms they already accepted would be noise. A first-time
     account created through the login button is caught by the post-sign-in
     gate instead. */
  const handoff = () => {
    trackEvent("oauth_start", { provider: "google", surface: context });
    auth.signInWithProvider("google");
  };
  return (
    <React.Fragment>
      <button
        type="button"
        className="auth-btn auth-btn-provider"
        onClick={() => {
          if (onNeedTermsConsent) onNeedTermsConsent("google", handoff);
          else handoff();
        }}
      >
        <GoogleMark />
        <span>Continue with Google</span>
      </button>
      <div className="auth-divider"><span>or</span></div>
    </React.Fragment>
  );
}

function AuthPasswordField({ id, label, value, onChange, autoComplete, meter, placeholder, onEnter }) {
  const [show, setShow] = useState(false);
  const score = meter ? authPasswordScore(value) : 0;
  return (
    <div className="auth-field">
      <label htmlFor={id}>{label}</label>
      <div className="auth-pw-row">
        <input
          id={id}
          type={show ? "text" : "password"}
          value={value}
          autoComplete={autoComplete}
          /* The signup and reset forms are setting a password and should say
             what the rule is. The login form is recalling one that already
             exists, where a minimum-length hint is noise at best and, for an
             older account, actively wrong. */
          placeholder={placeholder || "At least " + AUTH_MIN_PASSWORD + " characters"}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter" && onEnter) onEnter(); }}
        />
        <button
          type="button"
          className="auth-pw-toggle"
          aria-label={show ? "Hide password" : "Show password"}
          onClick={() => setShow((s) => !s)}
        >
          {show ? "HIDE" : "SHOW"}
        </button>
      </div>
      {meter && (
        <React.Fragment>
          <div className="auth-meter" aria-hidden="true">
            {[0, 1, 2, 3].map((i) => (
              <i key={i} className={i < score ? (score < 2 ? "warn" : "on") : ""} />
            ))}
          </div>
          <p className="auth-hint">
            {value.length === 0
              ? "Minimum " + AUTH_MIN_PASSWORD + " characters."
              : value.length < AUTH_MIN_PASSWORD
              ? "Too short \u2014 " + (AUTH_MIN_PASSWORD - value.length) + " more."
              : score >= 3
              ? "Strong."
              : "Fine. Longer is better."}
          </p>
        </React.Fragment>
      )}
    </div>
  );
}

/* Sign in. Replaces the Netlify widget's login form - not because signing in
   sends mail (it doesn't) but because the widget's form carries a "Forgot
   password?" link straight to GoTrue /recover, which mails Netlify's own
   unbranded recovery template. Our forgot link goes to ForgotPanel and
   auth-forgot.mts instead.

   GoTrue's error bodies are inconsistent across failure modes (error_description
   on some, msg on others, plain text on a gateway hiccup), and none of them is
   phrasing to show a person. Everything that isn't a network failure is
   reported as bad credentials, which is what it almost always is - and saying
   only that avoids confirming which half was wrong. */
function LoginPanel({ auth }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);

  const canSubmit = email.trim().length > 3 && password.length > 0 && !busy;

  async function submit() {
    if (!canSubmit) return;
    setBusy(true);
    setErr(null);
    trackEvent("login_submit", {});
    try {
      await auth.signIn(email.trim(), password);
      trackEvent("login_success", {});
      // No navigation needed: setStatus("in") re-renders the app behind this
      // panel and clears authPanel in the same update.
    } catch (e) {
      if (e && e.message === "WIDGET_FALLBACK") {
        trackEvent("login_error", { reason: "widget_fallback" });
        return;
      }
      const offline = typeof navigator !== "undefined" && navigator.onLine === false;
      setErr(
        offline
          ? "You appear to be offline. Check your connection and try again."
          : "That email and password don't match an account."
      );
      trackEvent("login_error", { reason: offline ? "offline" : "bad_credentials" });
    } finally {
      setBusy(false);
    }
  }

  return (
    <AuthOverlay onClose={auth.closeAuthPanel} label="Sign in">
      <div className="authcard">
        <AuthCloseButton onClose={auth.closeAuthPanel} />
        <p className="auth-eyebrow">Welcome back</p>
        <h1 className="auth-title">Sign in.</h1>

        <AuthProviderBlock auth={auth} context="login" />

        <div className="auth-fields">
          <div className={"auth-field" + (err ? " has-err" : "")}>
            <label htmlFor="li-email">Email</label>
            <input
              id="li-email" type="email" value={email} autoComplete="email"
              placeholder="you@example.com"
              onChange={(e) => { setEmail(e.target.value); if (err) setErr(null); }}
              onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
            />
          </div>
          <div className={err ? "has-err" : ""}>
            <AuthPasswordField
              id="li-pass" label="Password" value={password}
              onChange={(v) => { setPassword(v); if (err) setErr(null); }}
              autoComplete="current-password"
              placeholder="Your password"
              onEnter={submit}
            />
          </div>
        </div>

        {err && <p className="auth-err">{err}</p>}

        <div className="auth-actions">
          <button type="button" className="auth-btn auth-btn-primary" disabled={!canSubmit} onClick={submit}>
            {busy ? "Signing in\u2026" : "Sign in"}
          </button>
          <button type="button" className="auth-btn auth-btn-ghost" onClick={auth.closeAuthPanel}>
            Cancel
          </button>
        </div>

        <p className="auth-alt">
          <button type="button" className="auth-linkish" onClick={auth.openForgot}>
            Forgot your password?
          </button>
        </p>
        <p className="auth-alt">
          No account yet?{" "}
          <button type="button" className="auth-linkish" onClick={auth.openSignup}>
            Create a free one
          </button>
        </p>
      </div>
    </AuthOverlay>
  );
}

/* Signup. On success it does NOT sign the person in - the account exists but
   is unverified, and signing them straight into an app whose every endpoint
   refuses them would show a broken dashboard instead of "check your email".
   It hands back to the caller, which shows the pending screen. */
function SignupPanel({ auth, onSignedUp, onNeedTermsConsent }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);

  /* Acceptance is a submit requirement alongside the email and password,
     not a separate screen. auth-signup.mts refuses a signup without it and
     stamps the version onto the account in the same call, so the account
     never exists in an un-accepted state. */
  const canSubmit =
    email.trim().length > 3 && password.length >= AUTH_MIN_PASSWORD && acceptedTerms && !busy;

  async function submit() {
    if (!canSubmit) return;
    setBusy(true);
    setErr(null);
    trackEvent("signup_submit", {});
    try {
      const res = await fetch("/.netlify/functions/auth-signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: email.trim(),
          password,
          fullName: name.trim(),
          acceptTerms: acceptedTerms,
        }),
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) {
        setErr({ code: body.code || "error", message: body.error || "Something went wrong. Try again." });
        trackEvent("signup_error", { reason: body.code || "unknown" });
        return;
      }
      trackEvent("signup_success", { emailSent: body.emailSent === false ? "no" : "yes" });
      onSignedUp({ email: email.trim(), emailSent: body.emailSent !== false });
    } catch (e) {
      setErr({ code: "network", message: "Couldn't reach the server. Check your connection and try again." });
      trackEvent("signup_error", { reason: "network" });
    } finally {
      setBusy(false);
    }
  }

  return (
    <AuthOverlay onClose={auth.closeAuthPanel} label="Create an account">
      <div className="authcard">
        <AuthCloseButton onClose={auth.closeAuthPanel} />
        <p className="auth-eyebrow">Free account</p>
        <h1 className="auth-title">Start picking.</h1>
        <p className="auth-sub">Leagues, confidence rankings and game alerts. No card, no trial.</p>

        <AuthProviderBlock auth={auth} context="signup" onNeedTermsConsent={onNeedTermsConsent} />

        <div className="auth-fields">
          <div className="auth-field">
            <label htmlFor="su-name">Display name <span className="auth-opt">(optional)</span></label>
            <input
              id="su-name" type="text" value={name} autoComplete="name"
              placeholder="How you'll show in standings"
              onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div className={"auth-field" + (err && err.code === "email_taken" ? " has-err" : "")}>
            <label htmlFor="su-email">Email</label>
            <input
              id="su-email" type="email" value={email} autoComplete="email"
              placeholder="you@example.com"
              onChange={(e) => { setEmail(e.target.value); if (err) setErr(null); }}
            />
            {err && err.code === "email_taken" && (
              <p className="auth-err">
                There's already an account with that email.{" "}
                <button type="button" className="auth-linkish" onClick={auth.openLogin}>Sign in</button>
                {" or "}
                <button type="button" className="auth-linkish" onClick={auth.openForgot}>reset your password</button>.
              </p>
            )}
          </div>
          <AuthPasswordField
            id="su-pass" label="Password" value={password} onChange={setPassword}
            autoComplete="new-password" meter
          />
          <label className="auth-terms-check">
            <input
              type="checkbox"
              checked={acceptedTerms}
              disabled={busy}
              onChange={(e) => {
                setAcceptedTerms(e.target.checked);
                trackEvent("terms_consent", {
                  action: e.target.checked ? "signup_checked" : "signup_unchecked",
                });
              }}
            />
            <span>
              I'm 18 or older and agree to the{" "}
              <a href={TERMS_URL} target="_blank" rel="noopener noreferrer">Terms of Service</a>
              {" and "}
              <a href={PRIVACY_URL} target="_blank" rel="noopener noreferrer">Privacy Policy</a>.
            </span>
          </label>
        </div>

        {err && err.code !== "email_taken" && <p className="auth-err">{err.message}</p>}

        <div className="auth-actions">
          <button type="button" className="auth-btn auth-btn-primary" disabled={!canSubmit} onClick={submit}>
            {busy ? "Creating\u2026" : "Create free account"}
          </button>
          <button type="button" className="auth-btn auth-btn-ghost" onClick={auth.closeAuthPanel}>
            Cancel
          </button>
        </div>

        <p className="auth-alt">
          Already have one?{" "}
          <button type="button" className="auth-linkish" onClick={auth.openLogin}>
            Sign in
          </button>
        </p>
      </div>
    </AuthOverlay>
  );
}

/* "Confirm your email." Shown INSTEAD of the app for an unverified signed-in
   account, exactly as SuspendedScreen is - same reasoning, and the server
   refuses the same set of endpoints in both cases.

   Also reached straight after signup, before any session exists, which is
   why the address is passed in rather than read from auth.user. */
function UnverifiedScreen({ email, onSignOut, onUseDifferent }) {
  const [state, setState] = useState("idle"); // idle | sending | sent | error
  const [cooldown, setCooldown] = useState(0);

  useEffect(() => {
    if (cooldown <= 0) return;
    const t = setTimeout(() => setCooldown((c) => c - 1), 1000);
    return () => clearTimeout(t);
  }, [cooldown]);

  async function resend() {
    if (state === "sending" || cooldown > 0) return;
    setState("sending");
    trackEvent("verify_resend", {});
    try {
      const res = await fetch("/.netlify/functions/auth-verify-resend", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });
      // The endpoint answers 202 whether or not the address exists - it is
      // deliberately not an address oracle - so there is nothing here to
      // branch on beyond "did the request itself work".
      setState(res.ok ? "sent" : "error");
      if (res.ok) setCooldown(30);
    } catch (e) {
      setState("error");
    }
  }

  return (
    /* onClose null => rendered as a page, with no backdrop and no way to
       dismiss. This is a gate, not something anyone opened. */
    <AuthOverlay onClose={null} label="Confirm your email">
      <div className="authcard authcard-center">
        <div className="auth-icon">{"\u2709\uFE0F"}</div>
        <p className="auth-eyebrow">One more step</p>
        <h1 className="auth-title">Confirm your email.</h1>
        <p className="auth-sub">We sent a link to</p>
        <span className="auth-addr">{email}</span>
        <p className="auth-sub" style={{ marginTop: 10 }}>
          Click it and you're in. The link expires in 24 hours.
        </p>

        {state === "sent" ? (
          <p className="auth-note is-ok">Sent. Give it a minute, then check your inbox again.</p>
        ) : state === "error" ? (
          <p className="auth-note is-err">
            Couldn't send that just now. Try again in a moment, or email{" "}
            <a href="mailto:support@blitz-odds.com">support@blitz-odds.com</a>.
          </p>
        ) : (
          <p className="auth-note">
            Nothing arrived? Check spam for a message from <strong>support@blitz-odds.com</strong>,
            then try again below.
          </p>
        )}

        <div className="auth-actions">
          <button
            type="button" className="auth-btn auth-btn-primary"
            disabled={state === "sending" || cooldown > 0}
            onClick={resend}
          >
            {state === "sending" ? "Sending\u2026" : cooldown > 0 ? "Resend in " + cooldown + "s" : "Resend the email"}
          </button>
          <button type="button" className="auth-btn auth-btn-ghost" onClick={onUseDifferent}>
            {onSignOut ? "Sign out" : "Use a different address"}
          </button>
        </div>
      </div>
    </AuthOverlay>
  );
}

/* Forgot password. Answers identically whether or not the address exists,
   matching auth-forgot.mts - a client that branched on the response would
   reintroduce the address oracle the endpoint was written to avoid. */
function ForgotPanel({ auth }) {
  const [email, setEmail] = useState("");
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);
  const [err, setErr] = useState(null);

  async function submit() {
    if (!email.trim() || busy) return;
    setBusy(true);
    setErr(null);
    trackEvent("password_forgot_submit", {});
    try {
      const res = await fetch("/.netlify/functions/auth-forgot", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim() }),
      });
      if (res.ok) setSent(true);
      else setErr("Something went wrong. Try again in a moment.");
    } catch (e) {
      setErr("Couldn't reach the server. Check your connection and try again.");
    } finally {
      setBusy(false);
    }
  }

  if (sent) {
    return (
      <AuthOverlay onClose={auth.closeAuthPanel} label="Reset link sent">
        <div className="authcard authcard-center">
          <AuthCloseButton onClose={auth.closeAuthPanel} />
          <div className="auth-icon">{"\uD83D\uDCE8"}</div>
          <h1 className="auth-title">Check your inbox.</h1>
          <p className="auth-sub">
            If there's an account with that address, a reset link is on its way. It expires in an hour.
          </p>
          <div className="auth-actions">
            <button type="button" className="auth-btn auth-btn-ghost" onClick={auth.openLogin}>
              Back to sign in
            </button>
          </div>
        </div>
      </AuthOverlay>
    );
  }

  return (
    <AuthOverlay onClose={auth.closeAuthPanel} label="Forgot password">
      <div className="authcard">
        <AuthCloseButton onClose={auth.closeAuthPanel} />
        <p className="auth-eyebrow">Password reset</p>
        <h1 className="auth-title">Can't get in?</h1>
        <p className="auth-sub">Give us the address on the account and we'll send a reset link.</p>
        <div className="auth-fields">
          <div className="auth-field">
            <label htmlFor="fg-email">Email</label>
            <input
              id="fg-email" type="email" value={email} autoComplete="email"
              placeholder="you@example.com"
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
        </div>
        {err && <p className="auth-err">{err}</p>}
        <div className="auth-actions">
          <button type="button" className="auth-btn auth-btn-primary" disabled={!email.trim() || busy} onClick={submit}>
            {busy ? "Sending\u2026" : "Send reset link"}
          </button>
          <button type="button" className="auth-btn auth-btn-ghost" onClick={auth.openLogin}>
            Back to sign in
          </button>
        </div>
      </div>
    </AuthOverlay>
  );
}

/* Set a new password, from the ?reset= token the email link carries. On
   success it signs the person straight in with the password they just
   chose - they typed it a second ago and making them type it again on a
   login form is a step that exists only because the code was easier to
   write that way. */
function ResetPanel({ auth, token, onDone }) {
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);
  const [dead, setDead] = useState(null); // "token_expired" | "token_invalid"

  async function submit() {
    if (password.length < AUTH_MIN_PASSWORD || busy) return;
    setBusy(true);
    setErr(null);
    trackEvent("password_reset_submit", {});
    try {
      const res = await fetch("/.netlify/functions/auth-reset", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token, password }),
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) {
        if (body.code === "token_expired" || body.code === "token_invalid") {
          setDead(body.code);
          trackEvent("password_reset_error", { reason: body.code });
          return;
        }
        setErr(body.error || "Something went wrong. Try again.");
        trackEvent("password_reset_error", { reason: body.code || "unknown" });
        return;
      }
      trackEvent("password_reset_success", {});
      try {
        await auth.signIn(body.email, password);
      } catch (e) {
        // Sign-in after a successful reset is a convenience, not the point.
        // The password IS changed; fall back to the login form.
        auth.openLogin();
      }
      onDone();
    } catch (e) {
      setErr("Couldn't reach the server. Check your connection and try again.");
    } finally {
      setBusy(false);
    }
  }

  if (dead) {
    return (
      <AuthOverlay onClose={onDone} label="Reset link problem">
        <div className="authcard authcard-center">
          <AuthCloseButton onClose={onDone} />
          <div className="auth-icon is-warn">{dead === "token_expired" ? "\u23F3" : "\u26A0\uFE0F"}</div>
          <h1 className="auth-title">
            {dead === "token_expired" ? "That link has expired." : "That link isn't valid."}
          </h1>
          <p className="auth-sub">
            {dead === "token_expired"
              ? "Reset links last an hour. Request a fresh one and it'll be in your inbox in a moment."
              : "It may already have been used. Request a new one to try again."}
          </p>
          <div className="auth-actions">
            <button type="button" className="auth-btn auth-btn-primary" onClick={() => { onDone(); auth.openForgot(); }}>
              Send a new link
            </button>
          </div>
        </div>
      </AuthOverlay>
    );
  }

  return (
    <AuthOverlay onClose={onDone} label="Set a new password">
      <div className="authcard">
        {/* Dismissable, and safe to dismiss: consumeToken only fires on
            submit, so closing this leaves the link in the email still
            usable for its remaining hour. */}
        <AuthCloseButton onClose={onDone} />
        <p className="auth-eyebrow">Password reset</p>
        <h1 className="auth-title">Choose a new password.</h1>
        <div className="auth-fields">
          <AuthPasswordField
            id="rs-pass" label="New password" value={password} onChange={setPassword}
            autoComplete="new-password" meter
          />
        </div>
        {err && <p className="auth-err">{err}</p>}
        <div className="auth-actions">
          <button
            type="button" className="auth-btn auth-btn-primary"
            disabled={password.length < AUTH_MIN_PASSWORD || busy}
            onClick={submit}
          >
            {busy ? "Saving\u2026" : "Set password & sign in"}
          </button>
        </div>
      </div>
    </AuthOverlay>
  );
}

/* The ?verified= outcome from auth-verify.mts's redirect. */
const VERIFY_BANNERS = {
  ok: { cls: "is-ok", icon: "\u2705", title: "Email confirmed.", body: "You're all set \u2014 your account is live." },
  expired: { cls: "is-warn", icon: "\u23F3", title: "That link expired.", body: "Confirmation links last 24 hours. Sign in and press Resend for a fresh one." },
  invalid: { cls: "is-err", icon: "\u26A0\uFE0F", title: "That link isn't valid.", body: "It may already have been used. If you're already confirmed, just sign in." },
  error: { cls: "is-err", icon: "\u26A0\uFE0F", title: "Something went wrong.", body: "We couldn't confirm the address. Sign in and press Resend to try again." },
};

function VerifyBanner({ status, email, onDismiss }) {
  const b = VERIFY_BANNERS[status];
  if (!b) return null;
  return (
    <div className={"verify-banner " + b.cls} role="status">
      <span aria-hidden="true">{b.icon}</span>
      <div>
        <strong>{b.title}</strong>
        <p>{status === "ok" && email ? email + " is verified and your account is live." : b.body}</p>
      </div>
      <button type="button" className="verify-banner-x" aria-label="Dismiss" onClick={onDismiss}>
        {"\u00D7"}
      </button>
    </div>
  );
}

/* Shown in place of the entire app when the signed-in account is suspended.
   Deliberately plain: no nav, no tabs, no week strip. Every one of those
   would be a control the server refuses, and offering them reads as the app
   being broken rather than as a decision somebody made.

   The reason is shown when an admin gave one, and omitted cleanly when they
   didn't - "Reason: " followed by nothing is worse than no line at all. The
   support address is the only action besides signing out, because appealing
   is genuinely the only thing they can do from here. */
function SuspendedScreen({ suspension, onSignOut }) {
  return (
    <div className="susp-screen">
      <div className="susp-card">
        <BrandWordmark height={26} />
        <h1 className="susp-title">Your account is suspended</h1>
        <p className="susp-copy">
          You can't make picks, join leagues or change settings while this is in place.
          Nothing has been deleted — your picks and league history are intact and come
          straight back if the suspension is lifted.
        </p>
        {suspension.reason && (
          <p className="susp-reason"><strong>Reason:</strong> {suspension.reason}</p>
        )}
        <p className="susp-copy">
          If you think this is a mistake, reply from the address on the account:{" "}
          <a href="mailto:support@blitz-odds.com">support@blitz-odds.com</a>.
        </p>
        <button type="button" className="danger-btn susp-btn" onClick={onSignOut}>
          Sign out
        </button>
      </div>
    </div>
  );
}

function App() {
  const auth = useAuth();
  const [themeMode, setThemeMode] = useThemeManager();
  const [sportsbookId, setSportsbookId] = useSportsbookManager();
  const [gameType, setGameType] = useGameTypeManager();
  const [tzId, setTzId, resolvedTz] = useTimezoneManager();
  // "weekHub" is a routing distinction, not a separate screen: it means
  // "the week view, opened on the week named in the URL". It has to stay a
  // distinct route name so the root route (which is also view:"week", with
  // tab:"home") doesn't get mistaken for it, but it renders as the week view.
  const [view, setView] = useState(() => {
    const r = getInitialRoute() || {};
    return r.view === "weekHub" ? "week" : (r.view || "week");
  });
  const [selectedWeek, setSelectedWeek] = useState(() => {
    const route = getInitialRoute();
    return route && (route.view === "game" || route.view === "weekHub") && route.week != null ? route.week : getDefaultWeek();
  });
  // Which section of the team page a link asked for, if any. Only ever set
  // from the initial URL - clicking through to a team in-app lands at the
  // top, the way it always has.
  const [teamFocus, setTeamFocus] = useState(() => {
    const route = getInitialRoute();
    return route && route.view === "team" ? (route.focus || null) : null;
  });
  const [selectedTeamId, setSelectedTeamId] = useState(() => {
    const route = getInitialRoute();
    return route && route.view === "team" ? route.teamId : null;
  });
  const [selectedGame, setSelectedGame] = useState(() => {
    const route = getInitialRoute();
    return route && route.view === "game" ? { week: route.week, awayAbbr: route.awayAbbr, homeAbbr: route.homeAbbr } : null;
  });
  const [favorites, setFavorites] = useState(loadFavorites);
  const [profile, setProfile] = useState(null);

  /* Games currently in progress, for the badge on the Games tab.
   *
   * Pinned to getDefaultWeek() rather than `selectedWeek` on purpose: the
   * badge answers "is football on right now", which has nothing to do with
   * which week someone happens to be browsing. Someone reading week 3 in
   * November should still see that today's games have kicked off.
   *
   * This is a second useLiveScores() subscription alongside WeekView's, not
   * a hoist of it - WeekView needs the map for whatever week is on screen,
   * which is usually but not always this one. The duplication is cheap:
   * fetchLiveScoresCached() dedupes overlapping calls, and with nothing
   * live the hook sits at IDLE_POLL_MS (5 minutes). It has to live at App
   * level regardless, since the bar is visible from every tab and WeekView
   * is unmounted on three of them. */
  const liveTabWeek = useMemo(() => getDefaultWeek(), []);
  const liveTabMap = useLiveScores(liveTabWeek);
  const liveGameCount = useMemo(
    () => Object.values(liveTabMap).filter((g) => g && g.state === "in").length,
    [liveTabMap]
  );
  // Non-null when the signed-in account has been suspended. Set from the
  // user-profile fetch below, which is the only endpoint that reports the
  // reason rather than a generic 401.
  const [suspension, setSuspension] = useState(null);

  /* Set when user-profile answers 403 email_unverified - same shape and same
     source as `suspension` above, and gated the same way further down. Holds
     the address so the pending screen can offer Resend without a second
     round trip. */
  const [unverified, setUnverified] = useState(null);

  /* Set straight after signup, BEFORE any session exists. Distinct from
     `unverified`: that one describes a signed-in account the server refuses,
     this one describes someone who has an account and hasn't signed in at
     all. Both render the same screen; only the way out differs. */
  const [awaitingVerify, setAwaitingVerify] = useState(null);

  /* The ?verified= outcome auth-verify.mts redirects back with, and the
     ?reset= token the reset email links to. Both are read once at mount and
     immediately stripped from the URL - left in place, a refresh would
     re-show the banner, and a reset token would sit in the address bar (and
     the browser history, and any screenshot) long after it was spent. */
  const [verifyResult, setVerifyResult] = useState(() => {
    try {
      const params = new URL(window.location.href).searchParams;
      const status = params.get("verified");
      if (!status || !VERIFY_BANNERS[status]) return null;
      return { status, email: params.get("email") || null };
    } catch (e) { return null; }
  });
  const [resetToken, setResetToken] = useState(() => {
    try { return new URL(window.location.href).searchParams.get("reset") || null; }
    catch (e) { return null; }
  });

  useEffect(() => {
    if (!verifyResult && !resetToken) return;
    try {
      const url = new URL(window.location.href);
      url.searchParams.delete("verified");
      url.searchParams.delete("email");
      url.searchParams.delete("reset");
      window.history.replaceState(window.history.state, "", url.pathname + url.search + url.hash);
    } catch (e) {}
  }, []);

  /* A confirmation that landed while the tab was already open and signed in
     needs the session's view of the account refreshed, or the app keeps
     showing the "confirm your email" screen against an account that is now
     confirmed. Clearing `unverified` alone isn't enough - the profile fetch
     has to run again, which it does once the user object changes. */
  useEffect(() => {
    if (!verifyResult || verifyResult.status !== "ok") return;
    trackEvent("verify_complete", { outcome: "ok" });
    setUnverified(null);
    setAwaitingVerify(null);
    if (auth.status === "in" && auth.refreshUser) auth.refreshUser();
  }, [verifyResult, auth.status]);

  /* Terms acceptance. The email signup form carries its own checkbox (see
     SignupPanel), so there is no interstitial on that route any more.
     `oauthConsentOpen` is the dialog in front of an OAuth provider, which
     has no form of ours to put a checkbox in; `termsGate` is the blocking
     post-sign-in one. Separate state because they answer to completely
     different triggers and can never both be open. */
  const [oauthConsentOpen, setOauthConsentOpen] = useState(null);
  const [termsGate, setTermsGate] = useState({ open: false, busy: false, error: null });

  const [showHowItWorks, setShowHowItWorks] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [activeTab, setActiveTab] = useState(() => getInitialTab(LEAGUES_UI_ENABLED));
  const [leagueTabResetKey, setLeagueTabResetKey] = useState(0);

  // A league invite link's ?joinCode=/?joinLeague= (see getInitialLeagueJoin)
  // that LeagueView should act on once auth is ready. Lives here rather
  // than inside LeagueView so it survives that component's leagueTabResetKey
  // remounts and so the "please sign in first" nudge below can fire even
  // before LeagueView has mounted at all.
  const [pendingJoin, setPendingJoin] = useState(getInitialLeagueJoin);
  const loginPromptedForJoinRef = useRef(false);

  // A /leagues/{id} link (what a last-call pick alert points at) opens that
  // league directly. Read once at mount - after that the URL follows the
  // user's clicks via syncLeagueRoute, not the other way round.
  const [initialLeagueId] = useState(() => {
    try {
      const route = parseLocationPath(window.location.pathname);
      return route && route.leagueId ? route.leagueId : null;
    } catch (e) { return null; }
  });

  // Which subtab that link meant. Two accepted forms, on purpose:
  //   /leagues/{id}/requests   - the canonical one, matching the rest of the
  //                              path-based routing
  //   /leagues/{id}?panel=...  - what join-request emails sent before the
  //                              path form existed. Nothing ever read it, so
  //                              those links landed on My Picks. They're
  //                              already in people's inboxes and can't be
  //                              recalled, so they're honoured here rather
  //                              than left broken.
  //
  // This applies only when nothing in-app has asked for a destination (see
  // the LeagueView props below). Falling back to it with `||` whenever
  // leagueIntent lacks a subtab would leak it: arriving on
  // /leagues/A/requests and later opening league B from Home would drop B on
  // Requests too, since that intent carries no leagueSubTab of its own.
  const [initialLeagueSubTabFromUrl] = useState(() => {
    const VALID = ["requests", "standings", "picks"];
    try {
      const route = parseLocationPath(window.location.pathname);
      if (route && route.leagueSubTab) return route.leagueSubTab;
      if (route && route.leagueId) {
        const panel = new URL(window.location.href).searchParams.get("panel");
        if (panel && VALID.includes(panel)) return panel;
      }
    } catch (e) {}
    return null;
  });

  // Called by LeagueView whenever the open league changes. Guarded on the
  // active tab so a background remount can't rewrite the URL out from under
  // whatever tab is actually showing.
  const syncLeagueRoute = useCallback((leagueId, subTab) => {
    try {
      if (activeTab !== "league") return;
      const desired = leagueId ? buildLeaguePath(leagueId, subTab) : buildTabPath("league");
      // ?panel= has been consumed into the subtab by now (see
      // initialLeagueSubTabFromUrl). Carrying it forward would leave a stale
      // param pinned to the address bar for the rest of the session, and it
      // would fight the path form on the next read.
      const search = new URLSearchParams(window.location.search);
      search.delete("panel");
      const suffix = search.toString() ? `?${search.toString()}` : "";
      if (window.location.pathname !== desired || window.location.search !== suffix) {
        window.history.replaceState(window.history.state, "", desired + suffix);
      }
    } catch (e) {}
  }, [activeTab]);

  function clearPendingJoin() {
    setPendingJoin(null);
    try {
      const url = new URL(window.location.href);
      url.searchParams.delete("joinCode");
      url.searchParams.delete("joinLeague");
      // The path form needs clearing too, or a refresh re-triggers the join.
      const path = /^\/join\//.test(url.pathname) ? buildTabPath("league") : url.pathname;
      window.history.replaceState(window.history.state, "", path + url.search + url.hash);
    } catch (e) {}
  }

  // Someone who clicked an invite link while signed out gets dropped on
  // Leagues (via getInitialTab above) but can't actually join yet - open
  // the sign-in widget for them once instead of leaving them to notice the
  // "Sign in" button themselves. Once: if they close it without signing
  // in, don't keep reopening it every render.
  useEffect(() => {
    if (!pendingJoin || auth.status !== "out" || loginPromptedForJoinRef.current) return;
    loginPromptedForJoinRef.current = true;
    auth.openLogin();
  }, [pendingJoin, auth.status]);

  /* Signing out used to leave you standing on whatever page you were on,
   * which for most of the pages worth being on is a page that only exists
   * for a signed-in user: the Home dashboard, /picks, a league's standings.
   * Those re-render into their signed-out state in place, so the result is
   * an empty-looking screen at a URL like /leagues/{id} that reads as
   * something breaking rather than as a sign-out.
   *
   * Only an "in" -> "out" transition counts. Arriving signed-out is the
   * common case and must not redirect - it would fight getInitialTab and
   * bounce anyone opening a shared /games or /news link straight to Home.
   * The initial status is "loading", so a first paint can't look like a
   * sign-out either.
   *
   * leagueIntent is reset alongside so a later tap on Leagues lands on the
   * list. Left alone it stays null, which means "no in-app navigation has
   * happened, so the URL decides" - and the URL at mount may still name the
   * league they just signed out of.
   */
  const prevAuthStatusRef = useRef(auth.status);
  useEffect(() => {
    const wasSignedIn = prevAuthStatusRef.current === "in";
    prevAuthStatusRef.current = auth.status;
    if (!wasSignedIn || auth.status !== "out") return;
    setLeagueIntent({});
    goHomeTab();
  }, [auth.status]);
  const [showTour, setShowTour] = useState(false);
  const tourAutoOfferedRef = useRef(false);

  // Tapping the League tab (or "My Leagues") while already on it is a
  // no-op for setActiveTab - same value in, no re-render, so LeagueView's
  // internal selectedLeagueId/managingLeagueId just sit wherever they were,
  // with no way back to the Leagues landing page except the small
  // "All Leagues" text link. Bumping this key forces LeagueView to remount
  // (and its state to reset) any time the tab is (re)selected, so the tab
  // icon always acts like "go home" the way a mobile tab bar should.
  // The Home dashboard links straight at a specific league page - "Create
  // League" should land on the create wizard, "View League" on that league,
  // the pending badge on that league's Requests tab. Previously every one of
  // these called goToLeaguesTab() with an argument it ignored, so they all
  // dumped the user on the leagues landing page instead.
  //
  // The intent rides in state rather than props because tapping the tab
  // bumps leagueTabResetKey, which remounts LeagueView; a prop would be
  // re-read on that remount and re-apply a stale destination.
  const [leagueIntent, setLeagueIntent] = useState(null);
  function goToLeaguesTab(intent) {
    // Normalises to an object even when called with nothing, because null
    // means something different: "no in-app navigation has happened, so the
    // URL the app was loaded with still decides." Collapsing the two let
    // Home -> Manage fall back to initialLeagueId and drop the user inside
    // whatever league was in the URL at mount, instead of on the list they
    // asked for. An empty object is an explicit "the leagues list, please".
    setLeagueIntent(
      typeof intent === "string" ? { leagueId: intent }
        : (intent && typeof intent === "object") ? intent
        : {}
    );
    setLeagueTabResetKey((k) => k + 1);
    setActiveTab("league");
  }

  function selectTab(tab) {
    if (tab === "league") {
      goToLeaguesTab();
      return;
    }
    // Re-tapping the tab you're already on returns you to the top of it,
    // the way a native tab bar does. Also pops back out of a team or game
    // page to the week view, since that's the tab's own root.
    if (tab === activeTab) {
      if (tab === "games" && view !== "week") { backToWeek(); return; }
      window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
      return;
    }
    setActiveTab(tab);
  }

  // Keeps the URL in sync with the selected tab. This wrote a hash before
  // ("/#news"); it now writes a real path ("/news") so the tab is crawlable
  // and, more to the point, linkable from a notification - Universal Links
  // and App Links match on path and can't see a fragment.
  //
  // Two things this must not do. It must not clobber a team or game URL:
  // those live under activeTab "games" and are maintained by selectTeam /
  // selectGame / backToWeek, so this only touches the address bar when the
  // week view is showing. And the very first run has to be replaceState,
  // not pushState - arriving on "/#news", or on "/news" directly, is not a
  // navigation the Back button should have to undo.
  const tabRouteSyncedRef = useRef(false);
  useEffect(() => {
    try {
      const first = !tabRouteSyncedRef.current;
      tabRouteSyncedRef.current = true;
      const write = (path) => {
        const url = path + window.location.search;
        if (first) window.history.replaceState(window.history.state, "", url);
        else stampAndPush({ tab: activeTab }, url);
      };

      if (activeTab !== "games") {
        // A specific league keeps its own deeper URL rather than being
        // flattened back to /leagues every time this effect runs.
        if (activeTab === "league" && /^\/leagues\/[^/]+\/?$/.test(window.location.pathname)) return;
        const desired = buildTabPath(activeTab);
        const clean = window.location.pathname.replace(/\/$/, "") || "/";
        const want = desired.replace(/\/$/, "") || "/";
        if (clean !== want || window.location.hash) write(desired);
        return;
      }

      // activeTab === "games": the path belongs to whatever view is up
      // (/teams/... and /games/{season}/... are maintained by selectTeam and
      // selectGame). Only correct the case where the week view is showing but
      // the URL is stale - another tab's path, the bare root, or a legacy
      // hash. Under HOME_TAB_ENABLED the week view's own home is /games, not
      // "/", so the root now counts as stale here where it previously was
      // the destination.
      if (view !== "week") return;
      const desired = buildTabPath("games");
      const clean = window.location.pathname.replace(/\/$/, "") || "/";
      const want = desired.replace(/\/$/, "") || "/";
      if (clean === want) {
        if (window.location.hash) write(desired);
        return;
      }
      if (isTabPath(clean) || isRootPath(clean)) write(desired);
    } catch (e) {}
  }, [activeTab, view]);

  // A notification carries /g/{gameId} rather than the canonical game URL,
  // so once it resolves, swap the address bar over to the real one. Done
  // with replaceState so Back doesn't return to the alias and re-resolve.
  useEffect(() => {
    try {
      const route = parseLocationPath(window.location.pathname);
      if (!route || !route.alias) return;
      const canonical = buildGamePath(route.week, route.awayAbbr, route.homeAbbr);
      window.history.replaceState({ view: "game", ...route }, "", canonical + window.location.search);
    } catch (e) {}
  }, []);


  // Cross-device settings sync for signed-in users. Signed-out users keep
  // using localStorage only (see useThemeManager/useSportsbookManager/
  // useTimezoneManager/loadFavorites-saveFavorites above) - these two
  // effects layer server persistence on top once someone's signed in,
  // without changing how those hooks work when they're not.
  const settingsLoadedForUserRef = useRef(null);
  // Nothing may be pushed to the account until the load below has settled.
  // Previously this was a one-shot "skip the next save" flag, which had two
  // failure modes that both ended in lost favorites:
  //   1. The flag was only armed *after* the load's `await` resolved, but
  //      the save effect ran in the same effect pass as the load - so on any
  //      sign-in where the GET took longer than the 600ms debounce (routine,
  //      since user-profile.mts does its own round trip to GoTrue before it
  //      even reads the blob), the save won the race and POSTed this
  //      device's state over the account's. On a browser with no local
  //      favorites yet - fresh device, cleared storage, Safari having
  //      evicted localStorage - that wrote favorites: [] and wiped them.
  //   2. If the fetched settings happened to change no state (an older
  //      profile with no settings.favorites, or values identical to local),
  //      the save effect never re-ran, so the flag stayed armed and silently
  //      swallowed the user's *next* real change instead.
  // The gate + last-synced comparison below replaces it: no POST can precede
  // the load, and a POST is skipped only when its payload genuinely matches
  // what we last loaded or saved, however many renders later that is.
  const [settingsHydrated, setSettingsHydrated] = useState(false);
  const lastSyncedSettingsRef = useRef(null);

  // On sign-in, fetch this user's saved settings and apply them over
  // whatever's currently on this device - "same setting every time they
  // log in" means the account's settings win, not the device's.
  useEffect(() => {
    if (auth.status !== "in" || !auth.user || !auth.user.id) return;
    if (settingsLoadedForUserRef.current === auth.user.id) return;
    settingsLoadedForUserRef.current = auth.user.id;
    let cancelled = false;
    (async () => {
      // Whatever this device had before the account's settings landed. Used
      // only for the empty-server case below.
      const localFavorites = favorites;
      try {
        const res = await auth.authenticatedFetch("/.netlify/functions/user-profile");
        if (cancelled) return;
        // A suspended account is refused here with a 403 carrying a stable
        // code (see lib/auth.mts). This is the one endpoint that reports the
        // reason rather than a bare 401, precisely so the app can say what
        // happened instead of bouncing them into a login that would succeed
        // and change nothing.
        if (res.status === 403) {
          const body = await res.json().catch(() => ({}));
          if (cancelled) return;
          if (body && body.code === "account_suspended") {
            setSuspension({ reason: body.reason || null, at: body.suspendedAt || null });
            trackEvent("account_suspended_block", {});
            return;
          }
          // The other gate in lib/auth.mts. Same handling for the same
          // reason: this endpoint is the only one that reports why, so it
          // is the only place the app can learn to show the right screen
          // rather than a generic failure.
          if (body && body.code === "email_unverified") {
            setUnverified({ email: body.email || (auth.user && auth.user.email) || "" });
            trackEvent("verify_block", {});
            return;
          }
        }
        if (!res.ok) return;
        const profile = await res.json();
        if (cancelled) return;
        setProfile(profile);
        const s = (profile && profile.settings) || {};
        const nextThemeMode = (s.themeMode === "light" || s.themeMode === "dark" || s.themeMode === "system") ? s.themeMode : themeMode;
        const nextSportsbookId = typeof s.sportsbookId === "string" ? s.sportsbookId : sportsbookId;
        const nextTzId = typeof s.tzId === "string" ? s.tzId : tzId;
        // The account wins, with one exception: if the account has no
        // favorites at all and this device does, keep the device's rather
        // than clearing them. That covers starring teams signed out and then
        // creating an account - without it those picks vanish on first login.
        const serverFavorites = Array.isArray(s.favorites) ? s.favorites : null;
        const nextFavorites = (serverFavorites && serverFavorites.length) ? serverFavorites
          : (serverFavorites && localFavorites.length) ? localFavorites
          : (serverFavorites || localFavorites);
        setThemeMode(nextThemeMode);
        setSportsbookId(nextSportsbookId);
        setTzId(nextTzId);
        setFavorites(nextFavorites);
        /* Mirror the account's flag onto this device, in BOTH directions.
           The auto-trigger reads the account rather than localStorage, so
           the device copy is no longer load-bearing - but an admin who
           resets someone's tour would otherwise leave a stale "1" here,
           and anything that reads loadTutorialSeen() later would disagree
           with the console. */
        if (s.tutorialSeen) saveTutorialSeen(); else clearTutorialSeen();
        // Seed the comparison with what the account now holds, so a pure
        // load never generates a POST - but a genuine change after it always
        // does, unlike the old one-shot flag. Note this records the
        // *server's* favorites, not nextFavorites: in the kept-local case
        // above they differ, and the difference is exactly what makes the
        // save effect push those local favorites up to the account.
        lastSyncedSettingsRef.current = JSON.stringify({
          themeMode: nextThemeMode,
          sportsbookId: nextSportsbookId,
          tzId: nextTzId,
          favorites: serverFavorites || nextFavorites,
        });
      } catch (e) {
        // Offline or a transient function error - keep whatever's on this
        // device rather than blocking the app on a failed fetch. Seed the
        // comparison from local state so we don't immediately push a
        // possibly-stale device snapshot over the account we failed to read;
        // only a deliberate change from here on will POST.
        if (!cancelled) {
          lastSyncedSettingsRef.current = JSON.stringify({ themeMode, sportsbookId, tzId, favorites });
        }
      } finally {
        if (!cancelled) {
          // Every path out of the try above must leave a baseline behind -
          // including the early `return` on a non-OK response, which would
          // otherwise unblock the save effect with nothing to compare
          // against and push this device's state over an account we never
          // successfully read.
          if (lastSyncedSettingsRef.current === null) {
            lastSyncedSettingsRef.current = JSON.stringify({ themeMode, sportsbookId, tzId, favorites });
          }
          setSettingsHydrated(true);
        }
      }
    })();
    return () => { cancelled = true; };
  }, [auth.status, auth.user]);

  useEffect(() => {
    if (auth.status === "out") {
      settingsLoadedForUserRef.current = null;
      lastSyncedSettingsRef.current = null;
      setSettingsHydrated(false);
      setProfile(null);
      setSuspension(null);
      setUnverified(null);
    }
  }, [auth.status]);

  /* ---------- Terms of Service acceptance ----------
     See the block comment above TermsConsentModal for the three surfaces.
     The email form's checkbox lives in SignupPanel and is enforced by
     auth-signup.mts; this is the wiring for the other two. */

  /* Consent before an OAuth handoff. Opened by AuthProviderBlock instead of
     redirecting straight out, because once the redirect happens the next
     screen is Google's and there is no checkbox of ours anywhere in it.
     Holds the pending provider so accepting can resume the exact handoff
     that was interrupted. */
  const requestOauthConsent = useCallback((provider, run) => {
    trackEvent("terms_consent", { action: "oauth_prompt" });
    setOauthConsentOpen({ provider, run });
  }, []);

  const acceptOauthConsent = useCallback(() => {
    const pending = oauthConsentOpen;
    setOauthConsentOpen(null);
    trackEvent("terms_consent", { action: "oauth_accepted" });
    /* Nothing is written here. There is no account yet, and after the
       redirect this page is gone - a localStorage handoff would have to
       survive a round trip through Google and still be there on return,
       which is exactly the fragile path the gate exists to make
       unnecessary. The returning session lands on the gate instead, which
       is one extra tap on a route most people won't take, in exchange for
       consent that is never inferred from a marker left in a browser. */
    if (pending && typeof pending.run === "function") pending.run();
  }, [oauthConsentOpen]);

  const declineOauthConsent = useCallback(() => {
    setOauthConsentOpen(null);
    trackEvent("terms_consent", { action: "oauth_declined" });
  }, []);

  /* Writes acceptance from the gate. The server stamps the version - see
     lib/terms.mts - so there is nothing to send but the fact of it. This is
     now the gate's path only: an account created through SignupPanel was
     stamped at creation by auth-signup.mts and never gets here. */
  const submitTermsAcceptance = useCallback(async (source) => {
    setTermsGate((g) => ({ ...g, busy: true, error: null }));
    try {
      const res = await auth.authenticatedFetch("/.netlify/functions/user-profile", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ acceptTerms: true, termsSource: source }),
      });
      if (!res.ok) throw new Error(`user-profile responded ${res.status}`);
      const updated = await res.json();
      setProfile(updated);
      setTermsGate({ open: false, busy: false, error: null });
      trackEvent("terms_consent", { action: "gate_accepted" });
    } catch (e) {
      // The account still hasn't accepted, so the gate stays up with an
      // error on it rather than closing. Failing open here would leave an
      // unaccepted account quietly using the app, which is the one outcome
      // this whole thing exists to prevent.
      setTermsGate({
        open: true,
        busy: false,
        error: "We couldn't save that. Check your connection and try again.",
      });
      trackEvent("terms_consent", { action: "record_failed" });
    }
  }, [auth]);

  // One-shot guard, reset on sign-out below: without it the gate would
  // re-log a "shown" event on every re-render.
  const termsGateTrackedRef = useRef(false);

  useEffect(() => {
    if (auth.status !== "in" || !profile) return;

    if (!profile.termsAcceptanceRequired) {
      termsGateTrackedRef.current = false;
      setTermsGate((g) => (g.open || g.error ? { open: false, busy: false, error: null } : g));
      return;
    }

    /* An account created through SignupPanel is stamped at creation and
       never reaches here. What does: accounts from before this shipped, a
       returning OAuth session, and everybody after a TERMS_VERSION bump. */
    if (!termsGateTrackedRef.current) {
      termsGateTrackedRef.current = true;
      trackEvent("terms_consent", { action: "gate_shown" });
    }
    setTermsGate((g) => (g.open ? g : { open: true, busy: false, error: null }));
  }, [auth.status, profile]);

  useEffect(() => {
    if (auth.status !== "out") return;
    termsGateTrackedRef.current = false;
    setTermsGate({ open: false, busy: false, error: null });
  }, [auth.status]);

  const declineTermsGate = useCallback(() => {
    trackEvent("terms_consent", { action: "gate_signout" });
    setTermsGate({ open: false, busy: false, error: null });
    auth.logout();
  }, [auth]);

  // Push local setting changes back to the account so they follow the user
  // to their next login/device. Debounced since favorites in particular can
  // change several times in quick succession (toggling a few teams).
  useEffect(() => {
    if (auth.status !== "in") return;
    // Never write before we've read - see the comment on settingsHydrated.
    if (!settingsHydrated) return;
    const payload = JSON.stringify({ themeMode, sportsbookId, tzId, favorites });
    if (payload === lastSyncedSettingsRef.current) return;
    const timer = setTimeout(() => {
      lastSyncedSettingsRef.current = payload;
      auth.authenticatedFetch("/.netlify/functions/user-profile", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ settings: { themeMode, sportsbookId, tzId, favorites } }),
      }).catch(() => {
        // Let the next change retry this - don't leave lastSynced claiming
        // the account holds something the POST never delivered.
        if (lastSyncedSettingsRef.current === payload) lastSyncedSettingsRef.current = null;
      });
    }, 600);
    return () => clearTimeout(timer);
  }, [themeMode, sportsbookId, tzId, favorites, auth.status, settingsHydrated]);

  useLiveSiteData(); // background-refreshes teams/players/schedule/history/preseason/playoffs; re-renders the app when they change
  useLiveOddsData(); // background-refreshes odds from the live blob store; re-renders the app when they change
  useLiveWeatherData(); // background-refreshes weather from the live blob store; re-renders the app when they change
  // Two calls, not one: a per-game page is reachable from a week other than
  // the one the week nav is sitting on (selectedGame carries its own week),
  // and a card there needs its frozen numbers just as much. Both are
  // unconditional so the hook order never varies; the second no-ops when no
  // game is open, and neither refetches a week already in the map.
  useFrozenPredictions(selectedWeek); // pre-kickoff model calls for the week on screen, so live/final cards don't recompute
  useFrozenPredictions(selectedGame ? selectedGame.week : null);
  useDocumentMeta(activeTab, view, selectedTeamId, selectedWeek, selectedGame); // keeps <title>/description (and OG/Twitter mirrors) matching the current view

  useEffect(() => { saveFavorites(favorites); }, [favorites]);

  // Repair a rotated push subscription on load, for the reader who never
  // opens Settings. The whole failure mode is invisible from the app - the
  // browser reports a live subscription either way - so waiting for someone
  // to go looking is waiting for them to notice alerts they were never told
  // stopped. Costs nothing when the endpoint is unchanged; see
  // reconcilePushSubscription.
  useEffect(() => {
    if (auth.status !== "in") return;
    let cancelled = false;
    reconcilePushSubscription(auth).then((result) => {
      if (cancelled || !result || result === "unchanged") return;
      if (result === "rotated") trackEvent("push_device_desync", { stage: "rotated" });
      else if (result === "failed") trackEvent("push_device_repair_failed", { stage: "load" });
      else trackEvent("push_device_repaired", { stage: "load" });
    });
    return () => { cancelled = true; };
  }, [auth.status, auth.user]);

  // Recovers view state on browser back/forward. pushState (below) only
  // updates the address bar - it doesn't touch React state on its own - so
  // without this listener the Back button would change the URL but leave
  // whatever view was already on screen in place.
  useEffect(() => {
    function onPopState() {
      const route = parseLocationPath(window.location.pathname);
      if (route && route.view === "team") {
        setSelectedTeamId(route.teamId);
        setSelectedGame(null);
        setGameOrigin(null);
        setTeamFocus(route.focus || null);
        setView("team");
        setActiveTab("games");
      } else if (route && route.view === "game") {
        setSelectedGame({ week: route.week, awayAbbr: route.awayAbbr, homeAbbr: route.homeAbbr });
        setSelectedWeek(route.week);
        // The league trail this entry was pushed with, if any (see
        // selectGame). Without it, stepping back into a game page opened
        // from a pick sheet would show the Games breadcrumb and a back
        // button pointing at the week view instead of the pool.
        setGameOrigin((window.history.state && window.history.state.origin) || null);
        setView("game");
        setActiveTab("games");
      } else if (route && route.tab) {
        // Tabs are real paths now, so Back out of /news has to put the tab
        // back as well as the view - otherwise the URL and the screen
        // disagree until the next click.
        setSelectedGame(null);
        setGameOrigin(null);
        setView("week");
        setActiveTab(route.tab === "league" && !LEAGUES_UI_ENABLED ? "games" : route.tab);
      } else {
        setSelectedGame(null);
        setGameOrigin(null);
        setView("week");
        setActiveTab("games");
      }
      // Restore where this entry was left. The scroll has to happen after the
      // state updates above have painted, or the page is still the old view's
      // height and the browser clamps the offset. Two rAFs is the cheapest
      // reliable "after the next paint".
      const st = window.history.state;
      const key = st && st.__k ? st.__k : "k0";
      historyKeyRef.current = key;
      const depth = st && typeof st.__d === "number" ? st.__d : 0;
      historyDepthRef.current = depth;
      setHistoryDepth(depth);
      const y = scrollPositionsRef.current.get(key);
      const target = typeof y === "number" ? y : 0;
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          window.scrollTo({ top: target, left: 0, behavior: "auto" });
        });
      });
    }
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  function toggleFavorite(teamId) {
    setFavorites(prev => prev.includes(teamId) ? prev.filter(t => t !== teamId) : [...prev, teamId]);
  }

  /* First-run auto-trigger, now account-scoped rather than device-scoped.
     It used to fire for anybody on their first visit, signed in or not.
     Half of what the tour explains is signed-in-only (Add to League, the
     per-game bell, the full write-up, Playbook), so running it at a
     signed-out reader spent nine of its steps on features they can't reach
     and taught them nothing about the free ones.

     The gate reads the ACCOUNT's flag, not the device's. localStorage is
     still mirrored both ways for the replay item, but it can't be the
     source of truth here: a reader who browsed signed out on this device
     before creating an account may already carry a `1` from the old
     signed-out tour, which would silently suppress the run their new
     account is supposed to get. Waiting for settingsHydrated is what makes
     `profile` trustworthy - before it lands, the absence of tutorialSeen
     means "not loaded yet", not "never seen".

     Still Games/week only (there have to be cards on screen to point at),
     still once per session via the ref, and still on a delay so the
     schedule and live scores have rendered before the tour measures
     anything. The trade-off worth naming: signed-out visitors, which is
     most of the search traffic, no longer get a tour at all. */
  useEffect(() => {
    if (TOUR_DISABLED_PENDING_REDESIGN) return;
    if (tourAutoOfferedRef.current) return;
    if (auth.status !== "in") return;
    if (!settingsHydrated) return;
    if (unverified) return; // the verification gate owns the screen
    const seenOnAccount = !!(profile && profile.settings && profile.settings.tutorialSeen);
    if (seenOnAccount) return;
    if (activeTab !== "games" || view !== "week") return;
    tourAutoOfferedRef.current = true;
    const timer = setTimeout(() => setShowTour(true), 1200);
    return () => clearTimeout(timer);
  }, [activeTab, view, auth.status, settingsHydrated, profile, unverified]);

  /* `tutorialSeen` on its own can't answer "did they finish it?" - Done and
     Skip both set it, so every account that has met the tour looks identical
     afterwards. The outcome and the step someone stopped at are recorded
     alongside it so the admin console can tell the difference, and so a
     support conversation ("they say they never saw the tutorial") has an
     answer better than a boolean. `tutorialSeenAt` is stamped client-side
     because the profile endpoint doesn't timestamp settings writes. */
  function markTutorialSeen(outcome, lastStep) {
    saveTutorialSeen();
    const patch = {
      tutorialSeen: true,
      tutorialOutcome: outcome || "skipped",
      tutorialLastStep: lastStep || null,
      tutorialSeenAt: new Date().toISOString(),
    };
    // Optimistic local update: the auto-trigger effect reads `profile`, and
    // without this a re-render before the POST lands would see the flag
    // still unset and offer the tour a second time.
    setProfile(p => (p ? { ...p, settings: { ...(p.settings || {}), ...patch } } : p));
    if (auth.status === "in") {
      auth.authenticatedFetch("/.netlify/functions/user-profile", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ settings: patch }),
      }).catch(() => {});
    }
  }

  /* `result` is null when the tour closed without ever rendering a step -
     see the mount effect. That isn't a run, so it isn't recorded as one. */
  function closeTour(result) {
    setShowTour(false);
    if (!result || !result.outcome) return;
    markTutorialSeen(result.outcome, result.lastStep);
  }

  function replayTour() {
    if (TOUR_DISABLED_PENDING_REDESIGN) return;
    // Belt and braces with the menu item's own visibility check: the tour
    // assumes an account throughout, and this is reachable from a second
    // surface if one is ever added.
    if (auth.status !== "in") return;
    // A manual replay (from the account menu's "Replay tutorial") should
    // work regardless of which tab/view someone's currently on, so jump
    // back to the Games/week view first - the tour's own steps handle
    // switching to Hot Picks etc. as they go.
    backToWeek();
    setShowTour(true);
  }

  /* Back should return the reader to the row they tapped, not the top of a
     30-game list. Browsers only restore scroll for real page loads, so an SPA
     has to keep the positions itself: stamp each history entry with an id,
     record scrollY against that id whenever we push away from it, and read it
     back on popstate. Ids live in memory only - a hard reload starts a fresh
     map, which matches what the browser would do anyway. */
  const scrollPositionsRef = useRef(new Map());
  const historyKeyRef = useRef("k0");
  const historyKeySeqRef = useRef(0);
  /* How many in-app pushes deep the current entry is, so the back chevron can
     tell "there's a screen behind this one" from "this is where they landed".
     Stamped into history state, which survives a reload on the same entry. */
  const historyDepthRef = useRef(
    (window.history.state && typeof window.history.state.__d === "number") ? window.history.state.__d : 0
  );
  const [historyDepth, setHistoryDepth] = useState(historyDepthRef.current);

  /** Records where we are, mints an id for the entry we're about to create,
   *  and pushes it. */
  function stampAndPush(state, path) {
    scrollPositionsRef.current.set(historyKeyRef.current, window.scrollY);
    historyKeySeqRef.current += 1;
    const key = "k" + historyKeySeqRef.current;
    historyKeyRef.current = key;
    historyDepthRef.current += 1;
    setHistoryDepth(historyDepthRef.current);
    window.history.pushState({ ...state, __k: key, __d: historyDepthRef.current }, "", path);
  }

  function selectTeam(teamId) {
    setSelectedTeamId(teamId);
    setSelectedGame(null);
    setGameOrigin(null);
    setTeamFocus(null);
    setView("team");
    setActiveTab("games");
    const path = buildTeamPath(teamId);
    if (window.location.pathname !== path) stampAndPush({ view: "team", teamId }, path);
    // Switching views doesn't remount the page - without this, clicking a
    // team while scrolled partway down a long week/schedule list lands on
    // the new view still scrolled to that same position instead of its top.
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }

  /* Where the game page was opened from, when that wasn't the Games tab.
     Today the only such caller is a league pick sheet; the page uses it for
     its breadcrumb, its two back buttons and the pick confirmation in the
     card footer. Stamped into history state as well as held here, so the
     browser's own Back/Forward through a game page keeps the league trail
     instead of silently reverting to "Home > Games". */
  const [gameOrigin, setGameOrigin] = useState(null);

  function selectGame(week, awayAbbr, homeAbbr, origin) {
    setSelectedGame({ week, awayAbbr, homeAbbr });
    setGameOrigin(origin || null);
    setView("game");
    setActiveTab("games");
    const path = buildGamePath(week, awayAbbr, homeAbbr);
    if (window.location.pathname !== path) {
      stampAndPush({ view: "game", week, awayAbbr, homeAbbr, origin: origin || null }, path);
    }
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }

  /** A game opened from a league's pick sheet. `game` is the picks-mine row
   *  (away/home/gameId), `origin` the league context the pick card built. */
  function openGameFromLeague(game, origin) {
    if (!game || !origin) return;
    trackEvent("league_game_details", {
      source: "pick_card",
      format: origin.format,
      away: game.away,
      home: game.home,
      locked: !!origin.locked,
      picked: origin.pickTeam ? "yes" : "no",
    });
    selectGame(origin.week, game.away, game.home, origin);
  }

  /** Return to the pick sheet a game page was opened from. */
  function backToLeaguePicks(origin) {
    const target = origin || gameOrigin;
    if (!target) { backToWeek(); return; }
    trackEvent("league_game_details", { source: "back_to_picks", format: target.format });
    setSelectedGame(null);
    setGameOrigin(null);
    setView("week");
    goToLeaguesTab({ leagueId: target.leagueId, leagueSubTab: "week", week: target.week });
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }

  // Back out of a team or game page to the week view it was opened from.
  // This used to target ROOT_TAB, which is "home" once HOME_TAB_ENABLED - so
  // every caller that means "back to Games" (the back chevron, the "Games"
  // breadcrumb crumb, GameView's onBack) was landing people on the Home tab
  // instead. The front-page behaviour ROOT_TAB gave is what goHomeTab is for,
  // and the wordmark now calls that.
  //
  // The route sync effect writes the URL when the tab changes; it can't help
  // here, because coming back from /teams/... the tab is already "games" and
  // the effect declines to overwrite a path it doesn't recognise as stale.
  // Hence the explicit push.
  function backToWeek() {
    setView("week");
    setSelectedGame(null);
    setGameOrigin(null);
    const already = activeTab === "games";
    setActiveTab("games");
    const path = buildTabPath("games");
    if (already && window.location.pathname !== path) {
      stampAndPush({ view: "week", tab: "games" }, path);
    }
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }

  /** The Home tab, for the first crumb in a breadcrumb trail. Distinct from
   *  backToWeek, which returns to the week view under the Games tab - with
   *  the Home tab enabled those are two different destinations, and a trail
   *  reading "Home › Games › ..." has to honour both. Falls back to
   *  backToWeek when Games owns "/" (HOME_TAB_ENABLED false), where the two
   *  genuinely are the same place. */
  function goHomeTab() {
    if (!HOME_TAB_ENABLED) { backToWeek(); return; }
    setView("week");
    setSelectedGame(null);
    setActiveTab("home");
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }

  const periods = getSelectablePeriods();

  /* Drives the two scroll-linked bits of the compact header: the hairline
     under the bar, and (on Home) the full wordmark shrinking into the small
     one. Written straight to style rather than through state so it doesn't
     re-render the app on every scroll frame. */
  useEffect(() => {
    let frame = 0;
    function apply() {
      frame = 0;
      const bar = document.querySelector(".hdr-bar");
      if (bar) bar.classList.toggle("is-scrolled", window.scrollY > 4);
      const brand = document.querySelector(".app-home .brand-row");
      const mark = document.querySelector(".hdr-mark");
      if (brand) {
        const p = Math.min(1, window.scrollY / 70);
        brand.style.opacity = String(1 - p);
        brand.style.transform = `scale(${1 - p * 0.22}) translateY(${-p * 14}px)`;
        brand.style.pointerEvents = p > 0.9 ? "none" : "";
        // Hand off: the small mark only appears as the big one leaves.
        if (mark) mark.style.opacity = String(p);
      } else if (mark) {
        mark.style.opacity = "";
      }
    }
    function onScroll() {
      if (!frame) frame = requestAnimationFrame(apply);
    }
    apply();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [activeTab, view]);

  /* What the compact mobile bar shows. The week view gets the week picker;
     everything else gets a label naming where you are, since the wordmark no
     longer tells you and the tall header that used to is gone. */
  const showWeekPill = activeTab === "games" && view === "week";
  const headerTitle = (() => {
    if (activeTab === "games" && view === "team") {
      const t = baseTeam(selectedTeamId);
      return { title: t ? t.name : selectedTeamId, sub: "Team" };
    }
    if (activeTab === "games" && view === "game" && selectedGame) {
      return {
        title: `${selectedGame.awayAbbr} @ ${selectedGame.homeAbbr}`,
        sub: getPeriodLabel(selectedGame.week),
      };
    }
    // Home renders the full wordmark below the bar, so a "Blitz Odds" title
    // in the bar as well would say it twice.
    if (activeTab === "home") return { title: null, sub: null };
    if (activeTab === "picks") return { title: PLAYBOOK_TAB_LABEL, sub: getPeriodLabel(selectedWeek) };
    if (activeTab === "news") return { title: "News", sub: null };
    if (activeTab === "league") return { title: "Leagues", sub: null };
    return { title: "Blitz Odds", sub: null };
  })();

  /* The bar's left slot carries a back chevron on any drilled-in view and the
     small wordmark otherwise. The in-content Breadcrumb back pill still
     exists (CSS hides it on mobile) because the tour clicks it by selector.
     
     It pops one level rather than jumping to the week view, so opening a team
     from a game page and backing out returns to that game rather than skipping
     it. When there's nothing behind this entry - someone landed straight on
     /teams/... from search or a shared link - there's no in-app screen to pop
     to, so it falls back to the week view. */
  const mobileBack = (activeTab === "games" && view !== "week")
    ? {
        label: "Back",
        onClick: () => {
          if (historyDepth > 0) window.history.back();
          else backToWeek();
        },
      }
    : null;

  // A suspended account gets this INSTEAD of the app, not on top of it.
  // Rendering the normal shell behind a modal would leave a signed-in-looking
  // UI whose every control silently fails - the server refuses all of them -
  // and it would invite them to keep trying. One screen, one way out.
  if (suspension) {
    return <SuspendedScreen suspension={suspension} onSignOut={auth.logout} />;
  }

  /* Signed in but unverified, or just signed up and not signed in at all.
     Same screen either way - see the state declarations above for why they
     are two variables. This one still replaces the app rather than sitting
     over it: every authenticated control behind it is one the server
     refuses, so showing them would be offering a wall of dead buttons.

     The deliberately-opened panels (signup, login, forgot, reset) are the
     opposite case and render as modals inside the app tree below. */
  if (unverified || awaitingVerify) {
    const pending = unverified || awaitingVerify;
    return (
      <UnverifiedScreen
        email={pending.email}
        onSignOut={Boolean(unverified)}
        onUseDifferent={() => {
          if (unverified) auth.logout();
          setUnverified(null);
          setAwaitingVerify(null);
        }}
      />
    );
  }


  return (
    <div className={"app" + (activeTab === "home" ? " app-home" : "")}>
      {/* One markup, two layouts. Above 720px `header.top` is the grid it has
          always been (spacer / centred wordmark / account cluster) and
          `.hdr-bar` is display:contents so its children land straight in that
          grid. Below 720px the inversion runs the other way: `header.top`
          goes display:contents and `.hdr-bar` becomes a real sticky 52px bar,
          which also lets it stick against `.app` rather than against a
          52px-tall header it would immediately scroll out of. */}
      <header className="top">
        <div className="hdr-bar">
          <div className="hdr-lead">
            {mobileBack ? (
              <button type="button" className="hdr-back" onClick={mobileBack.onClick} aria-label={mobileBack.label}>
                <ChevronIcon direction="left" size={17} />
              </button>
            ) : (
              <button type="button" className="hdr-mark" onClick={goHomeTab} aria-label="Blitz Odds home">
                <BrandWordmark height={21} className="brand-logo-mini" />
              </button>
            )}
          </div>
          <div className="hdr-center">
            {showWeekPill
              ? <HeaderWeekPill periods={periods} selectedWeek={selectedWeek} onSelectWeek={setSelectedWeek} />
              : (
                <span className="hdr-title">
                  {headerTitle.title || ""}
                  {headerTitle.sub && <span className="hdr-sub">{headerTitle.sub}</span>}
                </span>
              )}
          </div>
          <div className="header-right-cluster">
            <AccountButton
              auth={auth}
              profile={profile}
              onOpenSettings={() => setShowSettings(true)}
              onOpenHowItWorks={() => setShowHowItWorks(true)}
              onReplayTour={replayTour}
              onOpenAdmin={() => setShowAdmin(true)}
            />
          </div>
        </div>
        <div className="brand-row" onClick={goHomeTab}>
          <BrandWordmark height={76} className="brand-logo" />
          <h1 className="sr-only">Blitz Odds</h1>
        </div>
      </header>

      {/* Sits above the tab bar rather than inside a tab, because the outcome
          it reports is about the account, not about whatever page the link
          happened to land on. Dismissed by hand only - it is one line and
          auto-hiding it would lose the "that link expired" case for anyone
          who looked away for four seconds. */}
      {verifyResult && (
        <VerifyBanner
          status={verifyResult.status}
          email={verifyResult.email}
          onDismiss={() => setVerifyResult(null)}
        />
      )}

      <TabBar activeTab={activeTab} onSelectTab={selectTab} liveCount={liveGameCount} />

      {activeTab === "home" && HOME_TAB_ENABLED && (
        auth.status === "in" ? (
          <HomeDashboard
            auth={auth}
            profile={profile}
            week={selectedWeek}
            sportsbookId={sportsbookId}
            tz={resolvedTz}
            onOpenLeagues={goToLeaguesTab}
            onOpenGames={() => selectTab("games")}
            onOpenPlaybook={() => selectTab("picks")}
          />
        ) : (
          /* Sign-up in place. These used to navigate to the Leagues tab
             first, which left the sign-up modal sitting over the leagues
             landing page - a page a signed-out visitor can't do anything
             with, and one nothing else points at any more. */
          <HomeLanding
            week={selectedWeek}
            sportsbookId={sportsbookId}
            tz={resolvedTz}
            onOpenGames={() => selectTab("games")}
            onCreateLeague={() => auth.openSignup()}
            onJoinLeague={() => auth.openSignup()}
          />
        )
      )}

      {activeTab === "games" && (
        <>
          {view === "week" && (
            <>
              <div className={"cmd-bar" + (favorites.length > 0 ? "" : " cmd-bar-bare")}>
                <WeekNav periods={periods} selectedWeek={selectedWeek} onSelectWeek={setSelectedWeek} />
                {favorites.length > 0 && (
                  <>
                    <div className="cmd-divider" aria-hidden="true" />
                    <div className="cmd-favs">
                      {favorites.map((teamId) => {
                        const t = baseTeam(teamId);
                        if (!t) return null;
                        return (
                          <button
                            key={teamId}
                            type="button"
                            className="cmd-fav-btn"
                            onClick={() => selectTeam(teamId)}
                            title={t.name}
                            aria-label={t.name}
                          >
                            <TeamLogo teamId={teamId} size={26} />
                          </button>
                        );
                      })}
                    </div>
                  </>
                )}
                <GameTypePicker gameType={gameType} setGameType={setGameType} />
              </div>
            </>
          )}

          {view !== "week" && <FavoritesBar favorites={favorites} onSelect={selectTeam} />}

          {view === "week" ? (
            <WeekView week={selectedWeek} favorites={favorites} onToggleFavorite={toggleFavorite} onSelectTeam={selectTeam} onSelectGame={selectGame} sportsbookId={sportsbookId} tz={resolvedTz} auth={auth} gameType={gameType} />
          ) : view === "game" && selectedGame ? (
            <GameView
              week={selectedGame.week}
              awayAbbr={selectedGame.awayAbbr}
              homeAbbr={selectedGame.homeAbbr}
              favorites={favorites}
              onToggleFavorite={toggleFavorite}
              onSelectTeam={selectTeam}
              onBack={backToWeek}
              onGoHome={goHomeTab}
              sportsbookId={sportsbookId}
              tz={resolvedTz}
              auth={auth}
              gameType={gameType}
              leagueOrigin={gameOrigin}
              onBackToLeague={backToLeaguePicks}
            />
          ) : (
            <TeamView teamId={selectedTeamId} favorites={favorites} onToggleFavorite={toggleFavorite} onBack={backToWeek} onGoHome={goHomeTab} onSelectTeam={selectTeam} onSelectGame={selectGame} sportsbookId={sportsbookId} tz={resolvedTz} focus={teamFocus} />
          )}
        </>
      )}

      {activeTab === "picks" && (
        <PlaybookView
          week={selectedWeek}
          sportsbookId={sportsbookId}
          tz={resolvedTz}
          auth={auth}
          onSelectGame={selectGame}
          onOpenLeagues={goToLeaguesTab}
        />
      )}

      {activeTab === "news" && <NewsView />}

      {activeTab === "league" && LEAGUES_UI_ENABLED && (
        <LeagueView
          key={leagueTabResetKey}
          auth={auth}
          profile={profile}
          onRequestLogin={() => auth.openLogin()}
          tz={resolvedTz}
          pendingJoin={pendingJoin}
          onConsumePendingJoin={clearPendingJoin}
          initialLeagueId={leagueIntent ? (leagueIntent.leagueId || null) : initialLeagueId}
          initialSubTab={leagueIntent ? (leagueIntent.subTab || null) : null}
          initialLeagueSubTab={leagueIntent ? (leagueIntent.leagueSubTab || null) : initialLeagueSubTabFromUrl}
          initialWeek={leagueIntent ? (leagueIntent.week || null) : null}
          onOpenLeagueRoute={syncLeagueRoute}
          onGoHome={goHomeTab}
          onOpenGame={openGameFromLeague}
        />
      )}

      <footer className="app-footer">
        <p className="footer-gambling-notice">
          Blitz Odds is for informational and entertainment purposes only and does not accept wagers. Confirm all
          lines with a licensed sportsbook before placing a bet, and bet only where it is legal and you meet the
          minimum age in your jurisdiction.
          {" "}<strong>Gambling problem? Call or text 1-800-GAMBLER (1-800-426-2537), or visit</strong>
          {" "}<a href="https://www.ncpgambling.org" target="_blank" rel="noopener noreferrer" style={{ color: "inherit", textDecoration: "underline" }}>ncpgambling.org</a>.
        </p>
        <p>
          Sources: The Football Database (team stats), Pro-Football-Reference and NFL.com (schedules),
          SportsGameOdds (betting lines), ESPN (live scores and box scores), Open-Meteo (weather).
          {" "}<a href="/historical/index.html" className="archive-entry-link" data-archive-source="footer" style={{ color: "var(--text-dim)", textDecoration: "underline" }}>Historical results archive</a>
        </p>
        <p className="footer-legal">
          &copy; {new Date().getFullYear()} Blitz Odds. Not affiliated with or endorsed by the National Football
          League. Team names and marks are the property of their respective owners.
          {" "}<a href="/terms/" style={{ color: "inherit", textDecoration: "underline" }}>Terms of Service</a>
          {" \u00b7 "}<a href="/privacy/" style={{ color: "inherit", textDecoration: "underline" }}>Privacy Policy</a>
        </p>
      </footer>

      {/* Terms acceptance. Rendered last and above everything (z-index 3400)
          so the blocking variant covers whatever was already open when the
          profile came back needing acceptance. Only one can ever be up: the
          signup dialog belongs to a signed-out reader, the gate to a
          signed-in one. */}
      {oauthConsentOpen && !termsGate.open && (
        <TermsConsentModal
          mode="oauth"
          busy={false}
          error={null}
          onAccept={acceptOauthConsent}
          onDecline={declineOauthConsent}
        />
      )}
      {termsGate.open && (
        <TermsConsentModal
          mode="gate"
          busy={termsGate.busy}
          error={termsGate.error}
          onAccept={() => submitTermsAcceptance("gate")}
          onDecline={declineTermsGate}
        />
      )}

      {showAdmin && <AdminConsole auth={auth} onClose={() => setShowAdmin(false)} />}

      {showSettings && (
        <SettingsModal
          auth={auth}
          profile={profile}
          onProfileUpdated={setProfile}
          sportsbookId={sportsbookId}
          setSportsbookId={setSportsbookId}
          themeMode={themeMode}
          setThemeMode={setThemeMode}
          tzId={tzId}
          setTzId={setTzId}
          resolvedTz={resolvedTz}
          favorites={favorites}
          onToggleFavorite={toggleFavorite}
          onClose={() => setShowSettings(false)}
        />
      )}

      {showHowItWorks && (
        <HowItWorksModal onClose={() => setShowHowItWorks(false)} />
      )}

      {showTour && !TOUR_DISABLED_PENDING_REDESIGN && (
        <TutorialTour onClose={closeTour} setActiveTab={setActiveTab} auth={auth} />
      )}

      {/* The account panels, mounted alongside the app's other modals rather
          than replacing the page. Whatever someone was reading when they
          tapped "Create a free account" is still behind the card - which is
          usually the thing that made them want an account in the first
          place, and losing it was the whole problem with the full-page
          version.

          The reset panel is in here too even though it arrives from an email
          link rather than a tap: it lands on the site root, so there is
          always a page underneath, and dismissing it should put someone on
          that page rather than nowhere. */}
      {auth.authPanel === "signup" && (
        <SignupPanel
          auth={auth}
          onNeedTermsConsent={requestOauthConsent}
          onSignedUp={(result) => {
            auth.closeAuthPanel();
            setAwaitingVerify({ email: result.email });
          }}
        />
      )}
      {auth.authPanel === "login" && <LoginPanel auth={auth} />}
      {auth.authPanel === "forgot" && <ForgotPanel auth={auth} />}
      {resetToken && (
        <ResetPanel auth={auth} token={resetToken} onDone={() => setResetToken(null)} />
      )}
    </div>
  );
}

// ---- Boot -----------------------------------------------------------------
// Load the two large data seeds from their canonical files (see the note at
// the top of this file), then mount. Both fetches are same-origin static
// files on the CDN, so this is one quick round trip; if either fails (offline,
// file renamed) the app still mounts on the empty shape and useLiveSiteData()
// fills it in from site-data-current a moment later, exactly as it already
// does for a stale embedded seed.
//
// The prerendered content snapshot (static team/game/week pages inject one
// right after <body> for crawlers and link scrapers) is hidden HERE, at the
// moment React takes over, rather than by an inline script at the end of the
// page. That way a visitor on a slow connection keeps reading real content
// until the app is actually ready instead of staring at a blank screen.
const SEED_FILES = [
  ["/data/history.json", (doc) => { if (doc && Array.isArray(doc.weeks)) HISTORY_DATA = doc; }],
  ["/data/impact-players.json", (doc) => { if (doc && doc.players && typeof doc.players === "object") PLAYERS_DATA = doc; }],
];

async function loadSeed([url, apply]) {
  try {
    const res = await fetch(url, { credentials: "same-origin" });
    if (!res.ok) return;
    apply(await res.json());
  } catch (e) {
    // Keep the empty shape; the live refresh will supply the data.
  }
}

async function bootApp() {
  await Promise.all(SEED_FILES.map(loadSeed));
  resetTeamRecordCache(); // derived from HISTORY_DATA, which may have just changed
  // flushSync forces the first render to commit before we continue, so the
  // snapshot is hidden only once the live app is actually painted in #root -
  // React 18's createRoot().render() alone schedules the work and returns,
  // which left a blank frame between hiding one and painting the other.
  const root = ReactDOM.createRoot(document.getElementById('root'));
  ReactDOM.flushSync(() => root.render(<App />));
  const prerendered = document.getElementById("prerendered-content");
  if (prerendered) prerendered.style.display = "none";
  loadIdentityWidget();
}

// The Netlify Identity widget is its own bundled app (login modal, GoTrue
// client) and costs ~0.5 s of main-thread time on a mid-range phone. It
// used to be a deferred <script> in <head>, i.e. it ran before app.js and
// in front of the first paint on every page. Now it's injected after the
// first render; useAuth() waits for the event below and binds the moment
// it lands, so a signed-in session still restores - just a beat after the
// page is already readable.
function loadIdentityWidget() {
  if (window.netlifyIdentity) { window.dispatchEvent(new Event("blitz:identity-ready")); return; }
  const s = document.createElement("script");
  s.src = "https://identity.netlify.com/v1/netlify-identity-widget.js";
  s.async = true;
  s.onload = () => window.dispatchEvent(new Event("blitz:identity-ready"));
  s.onerror = () => window.dispatchEvent(new Event("blitz:identity-failed"));
  document.head.appendChild(s);
}

bootApp();
